import XCTest
@testable import WhiskyKit

final class PEImportScannerTests: XCTestCase {
    // Byte-exact minimal PE images (MS-spec layout) with one import:
    // descriptor RVA 0x2000 → thunk 0x2100 → DLL name 0x2200.
    // swiftlint:disable:next line_length
    private static let x64ImageHex = ""
    // swiftlint:disable:next line_length
    private static let x86ImageHex = ""

    private func writeImage(_ hex: String, suffix: String) throws -> URL {
        let url = FileManager.default.temporaryDirectory
            .appending(component: "pe-scan-\(suffix)-\(UUID().uuidString).exe")
        var data = Data()
        var index = hex.startIndex
        while index < hex.endIndex {
            let next = hex.index(index, offsetBy: 2)
            guard let byte = UInt8(hex[index..<next], radix: 16) else {
                XCTFail("invalid hex fixture")
                return url
            }
            data.append(byte)
            index = next
        }
        try data.write(to: url)
        PEImportScanner.invalidateCache(for: url)
        return url
    }

    func testScanDetectsD3D11ImportOnX64() throws {
        let url = try writeImage(Self.x64ImageHex, suffix: "x64")
        let profile = PEImportScanner.scan(url: url)
        XCTAssertNotNil(profile)
        XCTAssertEqual(profile?.architecture, .x64)
        XCTAssertTrue(profile?.graphicsAPIs.contains(.d3d11) == true)
        XCTAssertEqual(profile?.importedDLLs, ["d3d11.dll"])
        XCTAssertEqual(profile?.origins["d3d11.dll"], .importTable)
        try? FileManager.default.removeItem(at: url)
    }

    func testScanDetectsD3D9ImportOnX32() throws {
        let url = try writeImage(Self.x86ImageHex, suffix: "x86")
        let profile = PEImportScanner.scan(url: url)
        XCTAssertNotNil(profile)
        XCTAssertEqual(profile?.architecture, .x32)
        XCTAssertTrue(profile?.graphicsAPIs.contains(.d3d9) == true)
        XCTAssertEqual(profile?.origins["d3d9.dll"], .importTable)
        try? FileManager.default.removeItem(at: url)
    }

    func testFallbackStringScanFindsAPIWhenImportsAbsent() throws {
        // Zero the import directory entry so the structured scan finds
        // nothing; the DLL name remains embedded in the first 4 MB, so
        // the string fallback must still classify it.
        let url = try writeImage(Self.x86ImageHex, suffix: "fb")
        var data = try Data(contentsOf: url)
        data.replaceSubrange(0x58 + 96 + 8..<0x58 + 96 + 16, with: Data(repeating: 0, count: 8))
        try data.write(to: url)
        PEImportScanner.invalidateCache(for: url)

        let profile = PEImportScanner.scan(url: url)
        XCTAssertNotNil(profile)
        XCTAssertTrue(profile?.graphicsAPIs.contains(.d3d9) == true)
        XCTAssertEqual(profile?.origins["d3d9.dll"], .stringFallback)
        try? FileManager.default.removeItem(at: url)
    }

    func testCacheInvalidationRescansModifiedFile() throws {
        let url = try writeImage(Self.x64ImageHex, suffix: "cache")
        _ = PEImportScanner.scan(url: url)
        PEImportScanner.invalidateCache(for: url)
        let profile = PEImportScanner.scan(url: url)
        XCTAssertEqual(profile?.importedDLLs, ["d3d11.dll"])
        try? FileManager.default.removeItem(at: url)
    }

    func testMappedViewBoundsChecks() throws {
        let url = try writeImage(Self.x64ImageHex, suffix: "map")
        defer { try? FileManager.default.removeItem(at: url) }
        let view = MappedPEView(url: url)
        XCTAssertNotNil(view)
        XCTAssertNil(view?.scalar(UInt32.self, at: (view?.count ?? 0) + 1))
        XCTAssertNil(view?.bytes(at: -1, count: 4))
        XCTAssertNil(view?.cString(at: -5, maxLength: 8))
        XCTAssertEqual(view?.scalar(UInt32.self, at: 0x3C), 0x40)
    }
}
